/* Festival Rescue interface. The engine owns puzzle rules; this file owns play and presentation. */
window.TryvoRescue=(()=>{
 'use strict';
 const C=window.TryvoCampaign,E=window.TryvoRescueEngine,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let host,timer=null,playing=false,focusCell=null,flash='',recovered=false,showTrace=false,fitTown=false;
 const icons={tram:'<rect x="4" y="3" width="16" height="17" rx="5"/><path d="M7 7h10v6H7zM8 20l-2 3m10-3 2 3"/><circle cx="8" cy="17" r="1"/><circle cx="16" cy="17" r="1"/>',flag:'<path d="M5 22V3m0 1h13l-3 4 3 4H5"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-4a6 6 0 0 1 12 0v4M17 4a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5v2"/>',bolt:'<path d="m14 2-9 12h7l-2 8 9-13h-7z"/>',undo:'<path d="m8 4-5 5 5 5M3 9h10a7 7 0 0 1 0 14"/>',play:'<path d="m8 4 12 8-12 8z"/>',check:'<path d="m4 12 5 5L20 6"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',refresh:'<path d="M20 8a9 9 0 1 0 1 7M20 2v7h-7"/>'};
 const icon=(id)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]||icons.star}</svg>`;
 const button=(text,action,extra='',secondary=false)=>`<button class="rescue-button ${secondary?'rescue-secondary':''}" data-rescue="${action}" ${extra}>${text}</button>`;
 function state(){const s=host.getState();if(!E.valid(s.rescue)){if(s.rescue)recovered=true;s.rescue=E.fresh();}return s.rescue;}
 function current(){const s=state();if(!E.unlocked(s,s.selected)||!C.available(host.getState(),s.selected))s.selected=E.levels[0].id;const l=C.routeLevel(host.getState(),E.level(s.selected));s.drafts[l.id]||=E.draft(l);return {s,l,d:s.drafts[l.id]};}
 function cancel(){clearTimeout(timer);timer=null;playing=false;}
 function configure(api){host=api;}
 function scene(lit=false){return `<img class="festival-illustration ${lit?'festival-lit':''}" src="assets/festival-town.png" alt="A lantern-lit mountain town, a river crossing and a festival waiting for its guests" width="1536" height="1024">`;}
 function home(){
  const s=state(),done=E.levels.filter(l=>E.completed(s,l.id)).length,next=E.levels.find(l=>!E.completed(s,l.id))||E.levels[2],saved=s.drafts[s.selected],resumable=saved?.path.length>1&&!E.completed(s,s.selected);
  return `<section class="poster-intro"><div><h1>Try. Learn. Own it.</h1><p>A playable world where your decisions move the story forward.</p></div><span class="intro-note">A little more<br><strong>“I did that.”</strong></span></section>
  <section class="play-hero"><div class="hero-title"><span class="festival-label">Tonight’s adventure</span><h2>Festival Rescue</h2><p>Can you bring everyone to the festival?</p></div><a class="hero-world" href="#rescue" aria-label="Open Festival Rescue and plan your route">${scene(done===3)}<span class="preview-map-title">${icon('tram')} Festival Rescue</span><span class="preview-pin depot-pin">${icon('tram')}<small>Depot</small></span><span class="preview-pin festival-pin">${icon('flag')}<small>Festival</small></span><span class="map-preview-cta">Enter the town ${icon('play')}</span></a><div class="play-hero-copy"><div class="dispatch-character"><span class="mira-avatar">${window.TryvoArt.portrait()}</span><div><strong>A message from Mira</strong><span>Festival organiser</span></div></div><h3>The lanterns are ready.<br>Their makers are stranded.</h3><p>Connect the streets, collect the riders and reach the festival within nine repair tokens.</p><ol class="home-loop"><li><b>1</b><span><strong>Your plan</strong>Choose which streets to connect.</span></li><li><b>2</b><span><strong>Visible consequences</strong>Run the tram. See what needs to change.</span></li><li><b>3</b><span><strong>Your contribution</strong>See the choices behind the arrival.</span></li></ol><div class="play-hero-actions">${button((resumable?'Resume your route':done===3?'Revisit Festival Rescue':'Play Festival Rescue')+icon('play'),'enter',`data-level="${resumable?s.selected:next.id}"`)}<a href="#mission-library" class="hero-secondary">Explore the investigation missions</a></div><div class="hero-facts"><span>${icon('check')} No timer. Your pace.</span><span>${done} of 3 chapters restored</span></div></div></section>
  <section class="play-path"><div class="path-heading"><div><h2>One town. Three chapters.</h2><p>Each new arrival starts with a choice you make.</p></div><span class="caption">Your progress stays on this device</span></div><div class="episode-cards">${E.levels.map((l,i)=>{const complete=E.completed(s,l.id),open=E.unlocked(s,l.id);return `<button class="episode-card episode-${i}" data-rescue="enter" data-level="${l.id}" ${open?'':'disabled'}><span class="episode-symbol">${icon(complete?'check':open?i===0?'tram':i===1?'people':'bolt':'lock')}</span><span class="episode-copy"><small>Chapter ${i+1}${complete?' · Restored':''}</small><strong>${l.name}</strong><span>${['Find a way around the closure','Bring two groups together','Open the bridge. Connect the town.'][i]}</span></span><span class="episode-arrow">${open?'↗':'Locked'}</span></button>`;}).join('')}</div></section>`;
 }
 function label(l,id){const stop=l.stops.find(s=>s.at===id);return id===l.start?'Tram depot':id===l.end?(l.destination||'Festival gate'):stop?stop.name:id===l.switch?'Signal hut':id===l.gate?'Bridge':l.blocked.includes(id)?'Closed street':l.repairs[id]?'Repair site':'Street';}
 // Stable display coordinates preserve the existing puzzle graph and saved routes.
 function point(l,id){
  if(l.id==='first-light')return [[19,25],[32,28],[44,28],[57,32],[70,38],[87,31],[19,43],[32,45],[44,44],[57,49],[70,55],[86,52],[10,35],[30,54],[43,55],[57,57],[75,60],[93,39],[13,60],[31,64],[44,63],[57,66],[72,68],[86,66],[17,77],[31,76],[44,78],[57,79],[71,80],[86,80]][id];
  const c=id%l.cols,r=Math.floor(id/l.cols),x=12+c*77/(l.cols-1)+(r%2?1.2:-1.2),y=23+r*56/(l.rows-1)+(c%2?1.8:-1.8);
  return [x,y];
 }
 function poly(l,path){return path.map(id=>{const [x,y]=point(l,id);return `${x*10},${y*6.667}`;}).join(' ');}
 // Stable display coordinates preserve the existing puzzle graph and saved routes.
 function point(l,id){
  if(l.id==='first-light')return [[19,25],[32,28],[44,28],[57,32],[70,38],[87,31],[19,43],[32,45],[44,44],[57,49],[70,55],[86,52],[10,35],[30,54],[43,55],[57,57],[75,60],[93,39],[13,60],[31,64],[44,63],[57,66],[72,68],[86,66],[17,77],[31,76],[44,78],[57,79],[71,80],[86,80]][id];
  const c=id%l.cols,r=Math.floor(id/l.cols),x=12+c*77/(l.cols-1)+(r%2?1.2:-1.2),y=23+r*56/(l.rows-1)+(c%2?1.8:-1.8);
  return [x,y];
 }
 function poly(l,path){return path.map(id=>{const [x,y]=point(l,id);return `${x*10},${y*6.667}`;}).join(' ');}
 function routeSVG(l,path,small=false){
  const roads=[];for(let a=0;a<l.cols*l.rows;a++)for(const b of [a+1,a+l.cols])if(b<l.cols*l.rows&&E.adjacent(l,a,b))roads.push(`<polyline points="${poly(l,[a,b])}" class="${l.blocked.includes(a)||l.blocked.includes(b)?'closed-road':'open-road'}"/>`);
  const history=state().history.filter(r=>r.level===l.id);const previous=showTrace&&history.length?[{path:history[0].firstPlan},{path:history.at(-1).path}]:[];
  return `<svg class="route-lines ${small?'mini-route':''}" viewBox="0 0 1000 666.7" preserveAspectRatio="none" aria-hidden="true"><g class="town-roads">${roads.join('')}</g>${previous.map((r,i)=>`<polyline class="previous-route previous-${i}" points="${poly(l,r.path)}"/>`).join('')}<polyline class="route-outline" points="${poly(l,path)}"/><polyline class="route-plan" points="${poly(l,path)}"/><polyline class="tram-trail" points="${poly(l,path)}"/></svg>`;
 }
 function board(l,d,r){
  const last=d.path.at(-1),marker=r?d.path[E.evaluate(l,d.path).stopIndex]:l.start,[mx,my]=point(l,marker);
  return `<div class="rescue-board ${r?.success?'board-won':''}" style="--cols:${l.cols};--rows:${l.rows}" role="group" aria-label="${esc(l.name)} route board. Use arrow keys to move, Enter to connect a street."><img class="town-backdrop" src="assets/festival-town.png" alt="" width="1536" height="1024">${routeSVG(l,d.path)}<div class="street-grid">${Array.from({length:l.cols*l.rows},(_,id)=>{
   const stop=l.stops.find(s=>s.at===id),blocked=l.blocked.includes(id),selected=d.path.includes(id),near=E.adjacent(l,last,id)&&!blocked&&!selected&&last!==l.end,[x,y]=point(l,id);
   const art=id===l.start?icon('tram'):id===l.end?icon('flag'):stop?window.TryvoArt.portrait():id===l.switch?icon('bolt'):id===l.gate?'<span class="bridge-glyph">≋</span>':blocked?'<span class="closure-mark">!</span>':'<span class="street-dot"></span>';
   return `<button class="street ${selected?'on-route':''} ${near?'connectable':''} ${blocked?'street-closed':''} ${stop?'pickup':''} ${id===l.start?'depot':''} ${id===l.end?'festival-gate':''} ${id===l.switch?'signal-hut':''} ${id===l.gate?'river-bridge':''}" style="left:${x}%;top:${y}%" data-rescue="cell" data-cell="${id}" aria-label="Row ${Math.floor(id/l.cols)+1}, column ${id%l.cols+1}: ${label(l,id)}${blocked?'':', cost '+E.cellCost(l,id)}${selected?', on your route':near?', connectable':''}" aria-pressed="${selected}" ${blocked?'aria-disabled="true"':''} tabindex="${id===(focusCell??l.start)?0:-1}"><span class="cell-art">${art}</span>${l.repairs[id]?`<small class="repair-cost">${l.repairs[id]}</small>`:''}${(stop||id===l.start||id===l.end||id===l.switch)?`<span class="cell-tag">${id===l.start?'Depot':id===l.end?(l.destination||'Festival'):id===l.switch?'Signal':stop.people+' riders'}</span>`:''}</button>`;
  }).join('')}</div><div class="moving-tram" style="left:${mx}%;top:${my}%" aria-hidden="true">${icon('tram')}</div></div>`;
 }
 function contribution(l,d){const history=state().history.filter(r=>r.level===l.id),last=history.at(-1);return `<div class="contribution-mini"><div class="contribution-title"><strong>Your attempt</strong><span>${history.length} ${history.length===1?'test run':'test runs'}</span></div><div class="attempt-line"><i></i><span>Current plan</span><b>${E.cost(l,d.path)} tokens</b></div>${last?`<div class="attempt-line previous"><i></i><span>First submitted plan</span><b>${E.cost(l,history[0].firstPlan)} tokens</b></div><div class="attempt-line latest"><i></i><span>Last tested plan</span><b>${last.cost} tokens</b></div><p>${last.success?'All riders arrived.':esc(E.evaluate(l,last.path).message)}</p>${button(showTrace?'Hide earlier routes':'Compare earlier routes','compare','aria-pressed="'+showTrace+'"',true)}`:'<p>Your first test run starts the record. Every revision is yours.</p>'}<p class="guidance-label">${d.hint?'Nudge opened for this plan':'No in-game guidance opened for this plan'}</p></div>`;}
 function resultCard(l,d,r){const evaluated=E.evaluate(l,r.path);return `<section class="run-outcome ${r.success?'outcome-won':'outcome-retry'}" id="run-outcome" tabindex="-1"><span class="outcome-symbol">${icon(r.success?'star':'refresh')}</span><div><span class="small-label">${r.success?'You made this happen':'A useful test run'}</span><h2>${r.success?'They made it. Because of your route.':'Your plan has one more turn in it.'}</h2><p>${esc(evaluated.message)}</p>${r.success?`<blockquote>“${esc(l.reply)}”<cite>Mira · Festival organiser</cite></blockquote>`:''}<div class="outcome-actions">${r.success?'':button('Keep building','keep')} ${button(r.success?'Try a different route':'Start a fresh route','clear','',true)}</div>${r.success?C.handoff(host.getState(),l.id):''}<details class="route-receipt"><summary>Your contribution · ${r.path.length-1} connected streets</summary><p>${r.moves} route edits. ${r.cost} tokens used. ${r.hint?'Guidance was opened.':'No in-game guidance opened.'} Your first submitted plan had ${r.firstPlan.length-1} streets; your recorded route has ${r.path.length-1}.</p>${button('Replay my tram journey','replay',`data-record="${r.id}"`,true)}<p class="caption">A game achievement in this layout, not a measure of general intelligence.</p></details></div></section>`;}
 function render(){
  const {s,l,d}=current(),index=E.levels.indexOf(l),r=s.history.find(r=>r.id===d.lastId&&(!l.destination||r.destination===l.destination)),spent=E.cost(l,d.path),best=E.best(s,l.id);
  return `<section class="rescue-page">${C.context(host.getState(),l.id)}<div class="rescue-top"><a href="#explore">← Back to the town</a><span>Planning route ${index+1} of 3 · ${esc(l.name)}</span><button class="text-button" data-rescue="help">How to play</button></div><div class="rescue-heading"><div><h1>Festival Rescue</h1><p>${esc(l.brief)}</p></div><div class="chapter-pips" aria-label="Planning routes">${E.levels.map((x,i)=>`<button data-rescue="enter" data-level="${x.id}" aria-label="Route ${i+1}: ${esc(x.name)}" ${E.unlocked(s,x.id)&&C.available(host.getState(),x.id)?'':'disabled'} ${x.id===l.id?'aria-current="step"':''}>${E.completed(s,x.id)?icon('check'):i+1}</button>`).join('')}</div></div>${recovered?'<p class="notice">Festival save data could not be restored; a fresh route is available. Your other mission records are unchanged.</p>':''}
  <div class="rescue-layout"><div class="board-panel"><div class="map-stage"><div class="board-toolbar"><span class="map-title">${icon('tram')} Festival Rescue</span><div class="budget-pill ${spent>l.budget?'over-budget':''}"><span class="token-name">Repair tokens</span><span class="token-dots" aria-hidden="true">${Array.from({length:l.budget},(_,i)=>`<i class="${i<spent?'used':''}"></i>`).join('')}</span><strong>${spent} / ${l.budget}</strong><span class="token-used">used</span></div></div><div class="map-scroll ${fitTown?'fit-town':''}">${board(l,d,r)}</div><div class="map-bottom"><div class="board-key"><span><i class="key-route"></i>Your plan</span><span><i class="key-simulation"></i>Tram route (simulation)</span><span>${icon('people')}Pickup <i class="key-closed"></i>Obstruction</span></div><div class="board-actions">${button(icon('undo')+'Undo','undo',d.path.length<2?'disabled':'',true)}${button(icon('play')+(r?'Run again':'Run tram'),'run',d.path.length<2?'disabled':'')}</div></div><div class="arrival-banner" aria-hidden="true">${icon('check')} Riders arrive at the festival</div></div><div class="mobile-map-tools"><span>${fitTown?'Whole town · zoom in to connect streets':'Swipe the map sideways to explore'}</span>${button(fitTown?'Zoom in':'Fit town','fit','aria-pressed="'+fitTown+'"',true)}</div><div class="board-feedback"><p class="board-message" id="rescue-message" role="status">${esc(flash||'Start at the depot. Connect the highlighted neighbouring junctions, then run your tram.')}</p>${button(icon('refresh')+'Clear route','clear',d.path.length<2?'disabled':'',true)}</div><p class="map-rule">Each junction costs 1 token; numbered repairs cost more. Follow the marked connections. Tap an earlier junction to revise your route.</p></div>
  <aside class="dispatch-panel"><h2>Your plan. Your contribution.</h2><div class="play-step"><span class="step-number">1</span><div><h3>Your plan</h3><p>Connect streets and choose the pickups.</p><ul class="mission-checks">${l.stops.map(stop=>`<li class="${d.path.includes(stop.at)?'planned':''}"><span>${icon(d.path.includes(stop.at)?'check':'people')}</span><div><strong>${esc(stop.name)}</strong><small>${stop.people} riders · ${d.path.includes(stop.at)?'On your plan':'Waiting for a route'}</small></div></li>`).join('')}${l.switch!==null?`<li class="${d.path.includes(l.switch)&&d.path.indexOf(l.switch)<d.path.indexOf(l.gate)?'planned':''}"><span>${icon('bolt')}</span><div><strong>Open the bridge</strong><small>Signal hut before crossing</small></div></li>`:''}</ul></div></div><div class="play-step"><span class="step-number">2</span><div><h3>Visible consequences</h3><p>Run the tram to see where your plan succeeds or needs another turn.</p><div class="mini-town consequence-town" aria-hidden="true"><span>${icon('tram')}</span></div></div></div><div class="play-step"><span class="step-number">3</span><div><h3>Your contribution</h3><p>Your choices, revisions and resources used.</p>${contribution(l,d)}</div></div><div class="practice-note">${icon('star')}<p><strong>What you practise</strong>Planning under constraints, anticipating consequences and revising after feedback.</p></div><details class="route-rules" ${d.hint?'open':''}><summary>A little help, if you want it</summary>${button(d.hint?'Show the nudge again':'Need a nudge?','hint','',true)}${d.hint?`<p class="rescue-nudge">${esc(l.hint)}</p>`:''}<p>No timer. No penalty for trying again.</p></details>${best?`<div class="personal-best">${icon('star')} Your best route: <strong>${best.cost} tokens</strong></div>`:''}</aside>${r?resultCard(l,d,r):''}</div><p class="rescue-footnote">Fictional town. Your decisions. Progress saves on this device when storage is available.</p></section>`;
 }
 function journal(){const s=state(),done=E.levels.filter(l=>E.completed(s,l.id)).length;if(!s.history.length)return '';return `<section class="rescue-journal"><div><span class="festival-label">The city remembers</span><h2>${done} of 3 festival routes restored</h2><p>${s.history.length} test runs. Every revision was part of getting there.</p></div><div class="rescue-best-list">${E.levels.map(l=>{const b=E.best(s,l.id);return `<div><span>${esc(l.name)}</span><strong>${b?b.cost+' tokens':'Not restored'}</strong></div>`;}).join('')}</div><a class="rescue-button rescue-secondary" href="#rescue">Return to the festival ↗</a></section>`;}
 function records(){const s=state();if(!s.history.length)return '';return `<details class="rescue-records"><summary>Festival Rescue · your route records</summary><p>Best successful route per layout. Fewer tokens wins within the same layout. No live players or universal ability ranking.</p><div class="route-record-grid">${E.levels.map(l=>{const b=E.best(s,l.id);return `<article><h3>${esc(l.name)}</h3>${b?`<strong>${b.cost}<small> / ${l.budget} tokens</small></strong><p>${b.path.length-1} streets · ${b.moves} edits${b.hint?' · Guidance opened':''}</p>${button('Inspect my route','watch-best',`data-level="${l.id}"`,true)}`:'<p>Complete this layout to set a record.</p>'}</article>`;}).join('')}</div></details>`;}
 function paint(focus){const scroll=document.querySelector('.map-scroll')?.scrollLeft||0;host.render(false);const map=document.querySelector('.map-scroll');if(map)map.scrollLeft=scroll;if(focus!==undefined){const el=document.querySelector(`[data-cell="${focus}"]`);el?.focus({preventScroll:true});}}
 function message(text){flash=text;const el=document.querySelector('#rescue-message');if(el)el.textContent=text;else host.toast(text);}
 function animate(l,r){cancel();playing=true;document.querySelector('.rescue-board')?.classList.add('is-running');const result=E.evaluate(l,r.path),route=r.path.slice(0,result.stopIndex+1),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;document.querySelectorAll('.rescue-page [data-rescue]').forEach(b=>b.disabled=true);const marker=document.querySelector('.moving-tram');let i=0;
  const step=()=>{if(!document.querySelector('.rescue-board')){cancel();return;}const at=route[i];const [px,py]=point(l,at);marker.style.left=px+'%';marker.style.top=py+'%';document.querySelector(`[data-cell="${at}"]`)?.classList.add('tram-visited');const stop=l.stops.find(s=>s.at===at);if(stop)message(`${stop.people} ${stop.name.toLowerCase()} are aboard. Your route keeps going.`);else if(at===l.switch)message('Signal sent. The bridge is now open for your tram.');if(i++<route.length-1){timer=setTimeout(step,reduced?0:stop||at===l.switch?450:180);}else{playing=false;flash=result.message;paint();const out=document.querySelector('#run-outcome');out?.focus({preventScroll:true});out?.scrollIntoView({behavior:reduced?'instant':'smooth',block:'nearest'});}};
  if(reduced)i=route.length-1;message('Your tram is testing the route…');step();
 }
 function handle(action,b){const {s,l,d}=current();if(playing)return;
  if(action==='fit'){fitTown=!fitTown;paint();document.querySelector('[data-rescue=fit]')?.focus({preventScroll:true});return;}
  if(action==='compare'){showTrace=!showTrace;paint();document.querySelector('[data-rescue=compare]')?.focus({preventScroll:true});return;}
  if(action==='enter'){const next=E.level(b.dataset.level);if(!next||!E.unlocked(s,next.id)||!C.available(host.getState(),next.id)){host.toast('Continue the earlier chapters in your Lantern Festival first.');return;}s.selected=next.id;showTrace=false;focusCell=next.start;flash='';host.save();host.navigate('#rescue');return;}
  if(action==='cell'){const id=Number(b.dataset.cell);focusCell=id;try{if(E.edit(l,d,id)){flash=E.cost(l,d.path)>l.budget?'Your plan is over budget. You can test it, or cut back and try another route.':`${label(l,id)} connected. ${Math.max(0,l.budget-E.cost(l,d.path))} tokens remain.`;host.save();paint(id);}}catch(e){message(e.message);}return;}
  if(action==='undo'){if(d.path.length>1){d.path.pop();d.moves++;d.lastId=null;flash='Last street removed.';host.save();focusCell=d.path.at(-1);paint(focusCell);}return;}
  if(action==='clear'){s.drafts[l.id]=E.draft(l);focusCell=l.start;flash='A fresh route. Your earlier test runs are still recorded.';host.save();paint(focusCell);return;}
  if(action==='hint'){d.hint=true;d.lastId=null;host.save();paint();document.querySelector('.rescue-nudge')?.scrollIntoView({block:'nearest'});return;}
  if(action==='help'){host.modal('Your route. Your call.',`<p>Start at the depot marker. Connect a neighbouring street by tapping it or using arrow keys and Enter. Plum lines show your route; a dashed line follows the tram simulation.</p><p>Pick up every marked group before the festival gate. Each new junction costs one repair token; numbered sites cost the shown amount. Closed streets cannot be used. Visit the signal hut before the bridge in the final route.</p><p>Tap an earlier point on your route to cut back, or use Undo. Run your route to see what happens. There is no timer or penalty for trying again.</p>`);return;}
  if(action==='run'){if(d.path.length<2)return;const previous=s.history.find(r=>r.id===d.lastId);if(l.destination&&previous&&previous.destination!==l.destination)d.lastId=null;const r=E.run(s,l,d);if(l.destination&&!r.destination)r.destination=l.destination;host.save();animate(l,r);return;}
  if(action==='replay'){const r=s.history.find(r=>r.id===b.dataset.record);if(r)animate(l,r);return;}
  if(action==='keep'){document.querySelector('.rescue-board')?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});focusCell=d.path.at(-1);document.querySelector(`[data-cell="${focusCell}"]`)?.focus({preventScroll:true});return;}
  if(action==='watch-best'){const r=E.best(s,b.dataset.level);if(!r)return;const layout=E.level(r.level),preview=board(layout,{path:r.path},r).replaceAll('data-rescue="cell"','disabled').replaceAll('tabindex="0"','tabindex="-1"').replace('Use arrow keys to move, Enter to connect a street.','Recorded route preview.');host.modal(esc(layout.name)+' · your best route',`<p>${r.cost} of ${layout.budget} tokens · ${r.path.length-1} streets. ${r.hint?'Guidance opened.':'No in-game guidance opened.'}</p>${preview}<p>This is your recorded route. Your current working route is unchanged.</p>`);document.querySelector('#dialog').addEventListener('close',()=>document.querySelector('#dialog .rescue-board')?.remove(),{once:true});return;}
  if(action==='celebrate'){host.modal('Your Lantern Festival',C.finale(host.getState()));return;}
  if(action==='legacy-celebrate'){host.modal('You brought the city together.',`${scene(true)}<h3>Three routes. One festival.</h3><p>You found a way around the closure, picked up two groups, and opened the river crossing. Every arrival followed a route you designed.</p><p>Revisit a chapter to try a more efficient route, or explore a different kind of thinking in the original missions.</p><a class="rescue-button" href="#mission-library" data-rescue="leave-modal">Explore another challenge ↗</a>`);return;}
  if(action==='leave-modal'){document.querySelector('#dialog').close();}
 }
 document.addEventListener('click',ev=>{const b=ev.target.closest('[data-rescue]');if(!b||!host)return;handle(b.dataset.rescue,b);});
 document.addEventListener('keydown',ev=>{const b=ev.target.closest('[data-cell]');if(!b||playing)return;const {l}=current(),id=Number(b.dataset.cell),col=id%l.cols,row=Math.floor(id/l.cols);let next=id;if(ev.key==='ArrowRight')next=row*l.cols+Math.min(l.cols-1,col+1);else if(ev.key==='ArrowLeft')next=row*l.cols+Math.max(0,col-1);else if(ev.key==='ArrowDown')next=Math.min(l.rows-1,row+1)*l.cols+col;else if(ev.key==='ArrowUp')next=Math.max(0,row-1)*l.cols+col;else if(ev.key==='Home')next=row*l.cols;else if(ev.key==='End')next=row*l.cols+l.cols-1;else return;ev.preventDefault();focusCell=next;document.querySelectorAll('[data-cell]').forEach(el=>el.tabIndex=Number(el.dataset.cell)===next?0:-1);document.querySelector(`[data-cell="${next}"]`)?.focus();});
 return {configure,cancel,home,render,journal,records,scene,enter:id=>handle('enter',{dataset:{level:id}})};
})();
